import pypdf
from pypdf.generic import NameObject, ArrayObject, IndirectObject

reader = pypdf.PdfReader('/root/sc100-blank.pdf')

# Get all form field widget annotations from each page to find appearance state names
for page_num, page in enumerate(reader.pages):
    if '/Annots' in page:
        annots = page['/Annots']
        for annot_ref in annots:
            annot = annot_ref.get_object()
            ft = annot.get('/FT', '')
            t = annot.get('/T', '')
            if ft == '/Btn' or (not ft and '/AP' in annot):
                ap = annot.get('/AP', {})
                n_keys = []
                if '/N' in ap:
                    n = ap['/N']
                    if hasattr(n, 'keys'):
                        n_keys = list(n.keys())
                if n_keys:
                    print(f'Page {page_num+1}, Field: {t}, AP/N keys: {n_keys}')
